  end
endmodule

module majority(input a, input b, input c, output y);
  assign y = (a & b) | (b & c) | (a & c);
endmodule

module adder4(input [3:0] a, input [3:0] b, input cin, output [3:0] sum, output cout);
  assign {cout, sum} = a + b + cin;
endmodule

module dec38(input [2:0] a, input en, output [7:0] y);
  assign y = en ? (8'b1 << a) : 8'b0;
endmodule

module mux2(input a, input b, input s, output reg y);
  always @* begin
    if (s) y = b;
    else   y = a;
  end
endmodule

module alu4(input [3:0] a, input [3:0] b, input [1:0] op, output reg [3:0] y);
  always @* begin
    case (op)
      2'd0: y = a + b;
      2'd1: y = a - b;
      2'd2: y = a & b;
      default: y = a | b;
    endcase
  end
endmodule

module popcount(input [7:0] x, output reg [3:0] n);
  integer i;
  always @* begin
    n = 0;
    for (i = 0; i < 8; i = i + 1)
      n = n + x[i];
  end
endmodule

module dff(input clk, input d, output reg q);
  always @(posedge clk) q <= d;
endmodule

module reg4(input clk, input rst_n, input en, input [3:0] d, output reg [3:0] q);
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)  q <= 4'd0;
    else if (en) q <= d;
  end
endmodule

module counter4(input clk, input rst, output reg [3:0] count);
  always @(posedge clk) begin
    if (rst) count <= 4'd0;
    else     count <= count + 4'd1;
  end
endmodule

module tb;
  reg  a, b, cin;            // inputs: reg, because we drive them
  wire sum, cout;            // outputs: wire, because the DUT drives them
  full_adder dut(.a(a), .b(b), .cin(cin), .sum(sum), .cout(cout));
  initial begin
    $dumpfile("dump.vcd");   // record a waveform
    $dumpvars(0, tb);
    {a, b, cin} = 3'b000; #10;
    {a, b, cin} = 3'b011; #10;
    $display("sum=%b cout=%b", sum, cout);
    $finish;                 // end the simulation
  end
endmodule

integer i, errs;
initial begin
  errs = 0;
  for (i = 0; i < 8; i = i + 1) begin
    {a, b, cin} = i[2:0];
    #5;
    if ({cout, sum} !== a + b + cin) begin
      errs = errs + 1;
      $display("FAIL a=%b b=%b cin=%b", a, b, cin);
    end
