module traffic(input clk, input rst, output red, output green, output yellow);
  localparam RED = 2'd0, GREEN = 2'd1, YELLOW = 2'd2;
  reg [1:0] state, next;

  always @(posedge clk)             // state register
    if (rst) state <= RED; else state <= next;

  always @* begin                    // next-state logic
    case (state)
      RED:     next = GREEN;
      GREEN:   next = YELLOW;
      default: next = RED;
    endcase
  end

  assign red    = (state == RED);    // output logic
  assign green  = (state == GREEN);
  assign yellow = (state == YELLOW);
endmodule

always @* begin
  case (state)
    S0: next = x ? S1 : S0;
    S1: next = x ? S1 : S2;
    S2: next = x ? S1 : S0;
    default: next = S0;
  endcase
end
