module reg_n #(parameter N = 8)(input clk, input [N-1:0] d, output reg [N-1:0] q);
  always @(posedge clk) q <= d;
endmodule

// in another module:
reg_n #(.N(12)) u12(.clk(clk), .d(d12), .q(q12));
reg_n #(.N(3))  u3 (.clk(clk), .d(d3),  .q(q3));

module addn #(parameter N = 6)(input [N-1:0] a, input [N-1:0] b, input cin, output [N-1:0] sum, output cout);
  wire [N:0] c;
  assign c[0] = cin;
  genvar i;
  generate
    for (i = 0; i < N; i = i + 1) begin : fa
      full_adder f(.a(a[i]), .b(b[i]), .cin(c[i]), .sum(sum[i]), .cout(c[i+1]));
    end
  endgenerate
  assign cout = c[N];
endmodule

function [3:0] to_gray;
  input [3:0] x;
  begin
    to_gray = x ^ (x >> 1);
  end
endfunction

assign g = to_gray(b);

module ram16(input clk, input we, input [3:0] addr, input [7:0] din, output [7:0] dout);
  reg [7:0] mem [0:15];
  always @(posedge clk)
    if (we) mem[addr] <= din;
  assign dout = mem[addr];
endmodule

